package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Node;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Node_hasAttr_TriageGen2Test {

    @Test
    public void testHasAttr_NullAttributeKey() {
        Node node = new Node("baseUri", new Attributes());
        try {
            node.hasAttr(null);
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            assertEquals("attributeKey", e.getMessage());
        }
    }

    @Test
    public void testHasAttr_EmptyAttributeKey() {
        Node node = new Node("baseUri", new Attributes());
        assertTrue(node.hasAttr(""));
    }

    @Test
    public void testHasAttr_SingleAttribute() {
        Node node = new Node("baseUri", new Attributes().set("test", "value"));
        assertTrue(node.hasAttr("test"));
    }

    @Test
    public void testHasAttr_MultipleAttributes() {
        Node node = new Node("baseUri", new Attributes().set("test1", "value1").set("test2", "value2"));
        assertTrue(node.hasAttr("test1"));
        assertTrue(node.hasAttr("test2"));
    }

    @Test
    public void testHasAttr_NoAttributes() {
        Node node = new Node("baseUri", new Attributes());
        assertFalse(node.hasAttr("test"));
    }

    @Test
    public void testHasAttr_UnknownAttribute() {
        Node node = new Node("baseUri", new Attributes().set("test", "value"));
        assertFalse(node.hasAttr("unknown"));
    }

    @Test
    public void testHasAttr_NullAttributes() {
        Node node = new Node("baseUri", null);
        try {
            node.hasAttr("test");
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            assertEquals("attributes", e.getMessage());
        }
    }

    @Test
    public void testHasAttr_NullDocument() {
        Node node = new Node("baseUri", new Attributes());
        Document document = null;
        try {
            node.ownerDocument();
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            assertEquals("ownerDocument", e.getMessage());
        }
    }
}
